        ensures
            op == res,
    {
        unimplemented!()
    }

    #[verifier(external_body)]
    fn clone_response(op: &Self::Response) -> (res: Self::Response)
        ensures
            op == res,
    {
        unimplemented!()
    }

    #[verifier(external_body)]
    fn dispatch(&self, op: Self::ReadOperation) -> (result: Self::Response)
        ensures
            Self::dispatch_spec(self@, op) == result,
